// Parse incoming WAHA message
const body = $input.item.json;
const message = body.payload?.body || body.body || '';
const from = body.payload?.from || body.from || '';
const chatId = body.payload?.chatId || body.chatId || from;
const messageType = body.payload?.type || body.type || 'chat';
const hasMedia = body.payload?.hasMedia || body.hasMedia || false;
const mediaUrl = body.payload?.media?.url || body.mediaUrl || '';

// Detect command type
let commandType = 'unknown';
let extractedData = {};

const lowerMessage = message.toLowerCase().trim();

// Check for help command
if (lowerMessage === 'help' || lowerMessage === 'bantuan' || lowerMessage === '/help') {
  commandType = 'help';
}
// Check for zakat mal calculation
else if (lowerMessage.includes('hitung zakat mal') || lowerMessage.includes('zakat penghasilan') || lowerMessage.includes('zakat harta')) {
  commandType = 'zakat_mal';
  const amountMatch = message.match(/(\d+[.,]?\d*)/g);
  if (amountMatch) {
    let amount = amountMatch[0].replace(/\./g, '').replace(',', '.');
    extractedData.penghasilan = parseFloat(amount);
  }
}
// Check for zakat fitrah calculation
else if (lowerMessage.includes('hitung zakat fitrah') || lowerMessage.includes('zakat fitrah')) {
  commandType = 'zakat_fitrah';
  const peopleMatch = message.match(/(\d+)\s*(orang|jiwa|org|keluarga)/i);
  if (peopleMatch) {
    extractedData.jumlahJiwa = parseInt(peopleMatch[1]);
  } else {
    const numMatch = message.match(/(\d+)/);
    extractedData.jumlahJiwa = numMatch ? parseInt(numMatch[1]) : 1;
  }
}
// Check for invoice/donation input with more flexible parsing
else if (lowerMessage.includes('no.liq') || lowerMessage.includes('noliq') || 
         lowerMessage.includes('input') || lowerMessage.includes('catat') ||
         (lowerMessage.includes('nominal') && (lowerMessage.includes('donasi') || 
          lowerMessage.includes('shodaqoh') || lowerMessage.includes('sedekah') ||
          lowerMessage.includes('infaq') || lowerMessage.includes('zakat')))) {
  commandType = 'invoice_input';

  // Extract no.liq with multiple patterns
  const noLiqPatterns = [
    /no\.?\s*liq\.?\s*[:#]?\s*([\w\d\/-]+)/i,
    /noliq\.?\s*[:#]?\s*([\w\d\/-]+)/i,
    /nomor\s*[:#]?\s*([\w\d\/-]+)/i,
    /no\.?\s*[:#]?\s*([\w\d\/-]+)/i
  ];

  for (const pattern of noLiqPatterns) {
    const match = message.match(pattern);
    if (match) {
      extractedData.noLiq = match[1].trim();
      break;
    }
  }
  if (!extractedData.noLiq) extractedData.noLiq = '';

  // Extract nama donatur
  const namaPatterns = [
    /(?:dari|nama|donatur|atas\s*nama|an\.)\s*[:#]?\s*([A-Za-z\s]+?)(?=\s*(?:nominal|untuk|rp|\d|$))/i,
    /donatur\s*[:#]?\s*([A-Za-z\s]+)/i
  ];

  for (const pattern of namaPatterns) {
    const match = message.match(pattern);
    if (match) {
      extractedData.namaDonatur = match[1].trim();
      break;
    }
  }
  if (!extractedData.namaDonatur) extractedData.namaDonatur = '';

  // Extract nominal with comprehensive patterns
  let nominal = 0;
  const nominalPatterns = [
    /(?:nominal|rp\.?|idr|sejumlah)\s*[:#]?\s*([\d.,]+)\s*(ribu|rb|juta|jt|k|m)?/i,
    /([\d.,]+)\s*(ribu|rb|juta|jt|k|m)/i,
    /rp\.?\s*([\d.,]+)/i
  ];

  for (const pattern of nominalPatterns) {
    const match = message.match(pattern);
    if (match) {
      nominal = parseFloat(match[1].replace(/\./g, '').replace(',', '.'));
      const multiplier = match[2]?.toLowerCase();
      if (multiplier === 'ribu' || multiplier === 'rb' || multiplier === 'k') {
        nominal *= 1000;
      } else if (multiplier === 'juta' || multiplier === 'jt' || multiplier === 'm') {
        nominal *= 1000000;
      }
      break;
    }
  }
  extractedData.nominal = nominal;

  // Extract jenis donasi
  let jenis = 'Lainnya';
  if (lowerMessage.includes('shodaqoh') || lowerMessage.includes('sedekah') || lowerMessage.includes('sodaqoh') || lowerMessage.includes('shadaqah')) {
    jenis = 'Shodaqoh';
  } else if (lowerMessage.includes('infaq') || lowerMessage.includes('infak')) {
    jenis = 'Infaq';
  } else if (lowerMessage.includes('zakat fitrah')) {
    jenis = 'Zakat Fitrah';
  } else if (lowerMessage.includes('zakat mal') || lowerMessage.includes('zakat penghasilan') || lowerMessage.includes('zakat harta')) {
    jenis = 'Zakat Mal';
  } else if (lowerMessage.includes('zakat')) {
    jenis = 'Zakat';
  } else if (lowerMessage.includes('wakaf')) {
    jenis = 'Wakaf';
  } else if (lowerMessage.includes('fidyah')) {
    jenis = 'Fidyah';
  } else if (lowerMessage.includes('qurban') || lowerMessage.includes('kurban')) {
    jenis = 'Qurban';
  }
  extractedData.jenis = jenis;
}
// Check if it's an image
else if (hasMedia || messageType === 'image') {
  commandType = 'invoice_image';
  extractedData.mediaUrl = mediaUrl;
}

return {
  json: {
    from,
    chatId,
    message,
    messageType,
    hasMedia,
    mediaUrl,
    commandType,
    extractedData,
    timestamp: new Date().toISOString(),
    dateFormatted: new Date().toLocaleDateString('id-ID', { 
      day: '2-digit', 
      month: '2-digit', 
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    })
  }
};

