const ocrResult = $input.item.json;
let extractedData = { noLiq: '', namaDonatur: '', nominal: 0, jenis: 'Lainnya' };

try {
  const content = ocrResult.message?.content || ocrResult.choices?.[0]?.message?.content || '';
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    const parsed = JSON.parse(jsonMatch[0]);
    extractedData = {
      noLiq: parsed.noLiq || '',
      namaDonatur: parsed.namaDonatur || '',
      nominal: parseFloat(parsed.nominal) || 0,
      jenis: parsed.jenis || 'Lainnya'
    };
  }
} catch (e) {
  console.log('Error parsing OCR:', e.message);
}

const originalData = $('Parse Message').item.json;

return {
  json: {
    ...originalData,
    extractedData,
    ocrSuccess: extractedData.nominal > 0
  }
};

