// Konfigurasi Zakat Mal
const CONFIG = {
  HARGA_EMAS_PER_GRAM: 1200000, // Rp 1.200.000/gram (sesuaikan dengan harga terkini)
  NISAB_GRAM_EMAS: 85, // 85 gram emas
  TARIF_ZAKAT: 0.025 // 2.5%
};

const NISAB = CONFIG.HARGA_EMAS_PER_GRAM * CONFIG.NISAB_GRAM_EMAS; // ~Rp 102.000.000

const penghasilan = $json.extractedData.penghasilan || 0;
const chatId = $json.chatId;

let responseMessage = '';
let zakatAmount = 0;
let wajibZakat = false;

if (penghasilan <= 0) {
  responseMessage = `*Perhitungan Zakat Mal*\n\n` +
    `Mohon masukkan nominal penghasilan/harta.\n\n` +
    `Contoh: hitung zakat mal penghasilan 150000000`;
} else if (penghasilan >= NISAB) {
  wajibZakat = true;
  zakatAmount = Math.round(penghasilan * CONFIG.TARIF_ZAKAT);
  responseMessage = `*Perhitungan Zakat Mal*\n\n` +
    `Penghasilan/Harta: Rp ${penghasilan.toLocaleString('id-ID')}\n` +
    `Nisab (${CONFIG.NISAB_GRAM_EMAS} gram emas): Rp ${NISAB.toLocaleString('id-ID')}\n\n` +
    `Status: *WAJIB ZAKAT*\n\n` +
    `*Zakat yang harus dibayar:*\n` +
    `Rp ${zakatAmount.toLocaleString('id-ID')}\n` +
    `(2.5% x Rp ${penghasilan.toLocaleString('id-ID')})\n\n` +
    `_Semoga Allah SWT menerima zakat Anda dan menjadikannya pembersih harta serta penyuci jiwa._`;
} else {
  const kekurangan = NISAB - penghasilan;
  responseMessage = `*Perhitungan Zakat Mal*\n\n` +
    `Penghasilan/Harta: Rp ${penghasilan.toLocaleString('id-ID')}\n` +
    `Nisab (${CONFIG.NISAB_GRAM_EMAS} gram emas): Rp ${NISAB.toLocaleString('id-ID')}\n\n` +
    `Status: *BELUM WAJIB ZAKAT*\n` +
    `Kekurangan dari nisab: Rp ${kekurangan.toLocaleString('id-ID')}\n\n` +
    `Meskipun belum wajib, Anda tetap bisa bersedekah untuk mendapatkan pahala.`;
}

return {
  json: {
    chatId,
    penghasilan,
    nisab: NISAB,
    wajibZakat,
    zakatAmount,
    responseMessage
  }
};

// Konfigurasi Zakat Fitrah
const CONFIG = {
  HARGA_BERAS_PER_KG: 18000, // Rp 18.000/kg (sesuaikan dengan harga beras di daerah Anda)
  BERAS_PER_JIWA_KG: 2.5, // 2.5 kg atau 3.5 liter per jiwa
  BERAS_PER_JIWA_LITER: 3.5
};

const ZAKAT_PER_JIWA = CONFIG.HARGA_BERAS_PER_KG * CONFIG.BERAS_PER_JIWA_KG;

const jumlahJiwa = $json.extractedData.jumlahJiwa || 1;
const chatId = $json.chatId;

const totalBeras = jumlahJiwa * CONFIG.BERAS_PER_JIWA_KG;
const totalLiter = jumlahJiwa * CONFIG.BERAS_PER_JIWA_LITER;
const totalUang = Math.round(jumlahJiwa * ZAKAT_PER_JIWA);

const responseMessage = `*Perhitungan Zakat Fitrah*\n\n` +
  `Jumlah Jiwa: ${jumlahJiwa} orang\n\n` +
  `*Total Zakat Fitrah:*\n` +
  `Beras: ${totalBeras} kg (atau ${totalLiter} liter)\n` +
  `Uang: Rp ${totalUang.toLocaleString('id-ID')}\n` +
  `_(dengan harga beras Rp ${CONFIG.HARGA_BERAS_PER_KG.toLocaleString('id-ID')}/kg)_\n\n` +
  `*Rincian per jiwa:*\n` +
  `- ${CONFIG.BERAS_PER_JIWA_KG} kg beras\n` +
  `- atau Rp ${ZAKAT_PER_JIWA.toLocaleString('id-ID')}\n\n` +
  `*Catatan:*\n` +
  `Zakat fitrah wajib dikeluarkan sebelum shalat Idul Fitri.\n` +
  `Waktu terbaik: setelah terbenam matahari akhir Ramadhan sampai sebelum shalat Ied.\n\n` +
  `_Semoga Allah SWT menerima zakat Anda._`;

return {
  json: {
    chatId,
    jumlahJiwa,
    totalBeras,
    totalLiter,
    totalUang,
    responseMessage
  }
};
